const hideVorReference = row.row_type === "CALCULATION_ZONE"
  && row.to_node_id === null
  && row.to_name.split(" / ").some(marker => marker === "RCA" || marker === "EOC");
const rowClass = row.row_type === "PHYSICAL_LEG_SUMMARY"
  ? "nav-leg-heading-row"
  : row.row_type === "DESTINATION_INFO"
    ? "nav-destination-info-row"
    : "nav-leg-detail-row";
return (
  <Fragment key={row.sequence}>
  <tr
    className={rowClass}
    key={row.sequence}
    data-row-type={row.row_type}
    data-row-sequence={row.sequence}
  >
    {selectedVorStations.map((station, index) => {
      const vorReference = hideVorReference ? "" : station === null
        ? "—"
        : formatVorRadialDistance(
            station,
            row.to_latitude_deg,
            row.to_longitude_deg,
            roundingMode,
            radReciprocal,
          );
      return (
        <td
          className="vor-reference-cell derived-readonly-cell"
          key={vorColumns[index]!.id}
          title={station == null
            ? "VOR/DME基準局を選択してください。"
            : `${station.identifier} ${radReciprocal ? "RAD反方位" : "局からTOへのRAD"} / 距離（表示専用セル）`}
          data-display-text={vorReference}
